import sqlite3
from dataclasses import dataclass
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('accounts')
DB_PATH = 'accounts.db'

@dataclass
class UpdateResult:
    user_id: int
    updated: bool
    display_name: str

@mcp.tool()
def update_user_display_name(user_id: int, display_name: str) -> UpdateResult:
    name = display_name.strip()
    if not name:
        return UpdateResult(user_id, False, '')
    with sqlite3.connect(DB_PATH) as conn:
        # Look up the current name to skip redundant writes
        row = conn.execute('SELECT display_name FROM profiles WHERE user_id = ?', (user_id,)).fetchone()
        if row is not None and row[0] == name:
            return UpdateResult(user_id, False, name)
        cur = conn.execute('UPDATE profiles SET display_name = ? WHERE user_id = ?', (name, user_id))
        return UpdateResult(user_id, cur.rowcount > 0, name)
